<script setup>
import {computed,onMounted,ref} from 'vue'
import {Bell,Calendar,Check,Medal,Warning,FullScreen} from '@element-plus/icons-vue'
import api,{unwrap} from '../api'
import {useAuthStore} from '../store'
const auth=useAuthStore(),data=ref({tasks:[],stats:{},workload:[],notes:[],likes:[]}),weather=ref({hourly:[],current:{}}),day=ref(new Date().toISOString().slice(0,10)),expanded=ref(false),pointsOpen=ref(false),loading=ref(true)
const dayTasks=computed(()=>data.value.tasks.filter(t=>t.dueDate===day.value||t.createdAt===day.value))
const weekDays=computed(()=>Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-d.getDay()+1+i);return d.toISOString().slice(0,10)}))
const visibleWorkload=computed(()=>expanded.value?data.value.workload:data.value.workload.slice(14,28))
const visibleWeather=computed(()=>expanded.value?weather.value.hourly:weather.value.hourly.slice(0,6))
const visibleNotes=computed(()=>expanded.value?[...data.value.notes,...data.value.likes.map(item=>({...item,like:true}))]:[...data.value.notes,...data.value.likes.map(item=>({...item,like:true}))].slice(0,2))
const weatherAlerts=computed(()=>{const hours=weather.value.hourly||[],alerts=[];const rain=hours.filter(item=>item.rain>=50),hot=hours.filter(item=>item.temperature>=35),severe=hours.filter(item=>[65,67,75,82,86,95,96,99].includes(item.code));const span=list=>list.length?`${list[0].time.slice(11,16)}-${list[list.length-1].time.slice(11,16)}`:'';if(severe.length)alerts.push({level:'danger',title:`${span(severe)} 强对流或灾害性天气风险`,tip:'暂停露天登高、起重和带电区域作业，人员撤至安全区域并关注预警。'});if(hot.length)alerts.push({level:'warning',title:`${span(hot)} 高温风险`,tip:'避开高温时段连续作业，落实轮换、补水和防暑监护。'});if(rain.length)alerts.push({level:'rain',title:`${span(rain)} 降雨概率较高`,tip:'巡视注意湿滑和能见度，检查防雨、防触电措施，禁止冒雨登高。'});return alerts})
const weatherSummary=computed(()=>weatherAlerts.value[0]?`${weatherAlerts.value[0].title}，${weatherAlerts.value[0].tip}`:'未来时段无明显气象风险，现场作业按标准落实安全措施。')
const rewardRows=computed(()=>[...data.value.tasks.filter(task=>task.status==='done').map(task=>({title:task.title,source:task.projectName||task.source,date:task.completedAt||task.dueDate,points:task.points||50,type:'任务核销'})),...data.value.likes.map(item=>({title:item.taskTitle,source:item.from,date:item.date,points:item.points,type:'师傅点赞'}))].sort((a,b)=>b.date.localeCompare(a.date)))
const weatherLabel=c=>c>=51&&c<=67?'有雨':c<=1?'晴':'多云'
async function load(){loading.value=true;try{const [dashboard,forecast]=await Promise.all([api.get('/dashboard'),api.get('/weather/hourly')]);data.value=unwrap(dashboard);weather.value=unwrap(forecast)}finally{loading.value=false}}
onMounted(load)
</script>
<template><div class="page dashx" :class="{expanded,'is-loading':loading}"><div v-if="loading" class="loading-skeleton"><el-skeleton animated :rows="10"/></div><div class="page-title"><div><p class="eyebrow">TODAY OVERVIEW</p><h1>{{auth.user?.name}}，今天一起把重点做扎实</h1><p>任务、日程与关键提醒集中呈现</p></div><div class="dash-head-actions"><div class="weather-brief"><div class="weather-now"><b>{{weather.current?.temperature_2m}}°</b><span>{{weather.city}} · {{weatherLabel(weather.current?.weather_code)}}</span><small>{{weather.live?'实时预报':'演示预报'}}</small></div><p>{{weatherSummary}}</p></div><el-button :icon="FullScreen" plain @click="expanded=!expanded">{{expanded?'收起':'展开'}}</el-button></div></div>
<div class="micro-kpis"><div class="progress-kpi"><span class="kpi-icon"><Check/></span><div><small>整体任务进度</small><b>{{data.stats.progress||0}}%</b><el-progress :percentage="data.stats.progress||0" :show-text="false" :stroke-width="6"/></div></div><div class="verify-kpi"><span class="kpi-icon"><Warning/></span><div><small>等待师傅核销</small><b>{{data.tasks.filter(t=>t.status==='verify').length}}<em>项</em></b><span>完成 100% 后人工确认</span></div></div><div class="point-kpi clickable" @click="pointsOpen=true"><span class="kpi-icon"><Medal/></span><div><small>本周成长积分</small><b>+{{data.stats.weeklyPoints||0}}<em>分</em></b><span>待获得 {{data.stats.pendingPoints||0}} 分 · 点击查看</span></div></div><div class="like-kpi"><span class="kpi-icon"><Bell/></span><div><small>师傅正向反馈</small><b>{{data.stats.likes||0}}<em>次</em></b><span>点赞同步奖励积分</span></div></div></div>
<section class="agenda spotlight"><header><div><p class="eyebrow">WEEKLY SCHEDULE</p><h2>本周日程</h2><span>选择日期，快速查看当天安排</span></div><strong>{{dayTasks.length}}<small>项安排</small></strong></header><div class="week-switch"><button v-for="d in weekDays" :key="d" :class="{active:d===day}" @click="day=d"><span>周{{['日','一','二','三','四','五','六'][new Date(d).getDay()]}}</span><b>{{d.slice(8)}}</b><i>{{data.tasks.filter(t=>t.dueDate===d||t.createdAt===d).length}}</i></button></div><div class="agenda-list"><article v-for="task in dayTasks" :key="task.id"><time>{{task.startTime||'待定'}}</time><div><b>{{task.title}}</b><span>{{task.projectName}} · {{task.assignee}}</span></div><el-progress :percentage="task.progress" :stroke-width="7"/><el-tag :type="task.priority==='P1'?'warning':'primary'">{{task.priority}}</el-tag></article><el-empty v-if="!dayTasks.length" description="当日无任务" :image-size="48"/></div></section>
<div class="dashx-grid"><section class="dx-panel mentor-board"><header><div><h2>师傅留言与叮嘱</h2><p>{{expanded?'执行前看一眼，关键步骤不遗漏':'最新提醒'}}</p></div><Bell/></header><article v-for="note in visibleNotes" :key="`${note.like?'l':'n'}${note.id}`" :class="{'like-note':note.like}"><i :class="note.tone"></i><div><b>{{note.like?`${note.from} 点赞了“${note.taskTitle}”`:note.tone==='safety'?'安全提醒':'今日重点'}}</b><p>{{note.like?note.comment:note.content}}</p><small>{{note.like?`奖励 +${note.points} 积分`:note.date}}</small></div></article><el-empty v-if="!visibleNotes.length" description="暂无留言"/></section>
<section class="dx-panel workload"><header><div><h2>工作量日历</h2><p>{{expanded?'五周工作负荷':'本周与下周'}}</p></div><Calendar/></header><div class="calendar-head"><span v-for="w in ['一','二','三','四','五','六','日']" :key="w">{{expanded?'周':''}}{{w}}</span></div><div class="heat-grid"><button v-for="item in visibleWorkload" :key="item.date" :class="[`lv${item.level}`,{active:day===item.date,today:item.date===new Date().toISOString().slice(0,10)}]" @click="day=item.date"><span>{{Number(item.date.slice(8))}}</span><small>{{item.workload}}</small></button></div><div class="heat-legend"><span>轻</span><i v-for="n in 5" :key="n" :class="`lv${n-1}`"></i><span>重</span></div></section>
</div><el-drawer v-model="pointsOpen" title="成长积分明细" size="420px"><div class="points-summary"><span>累计成长积分<b>{{data.stats.points||0}}</b></span><span>本周新增<b>+{{data.stats.weeklyPoints||0}}</b></span><span>待获得<b>{{data.stats.pendingPoints||0}}</b></span></div><div class="reward-drawer"><article v-for="item in rewardRows" :key="`${item.type}-${item.title}-${item.date}`"><div><el-tag size="small" effect="plain">{{item.type}}</el-tag><b>{{item.title}}</b><span>{{item.source}} · {{item.date}}</span></div><strong>+{{item.points}}</strong></article><el-empty v-if="!rewardRows.length" description="暂无积分记录"/></div></el-drawer></div></template>
<style scoped>
.dash-head-actions{display:flex;align-items:center;gap:14px}.weather-now{display:flex;align-items:baseline;gap:10px}.weather-now b{font-size:27px;color:#003b7a}.weather-now span{font-weight:700}.weather-now small{color:#8492a6}.spotlight{background:#fff;border:1px solid #dce5e4;border-left:5px solid #087c66;padding:16px 18px;margin-bottom:12px;box-shadow:0 5px 18px rgba(20,52,65,.07)}.spotlight header{display:flex;justify-content:space-between;align-items:end;margin-bottom:12px}.spotlight h2{font-size:19px;margin:1px 0}.spotlight header span{font-size:14px;color:#7e8b9c}.spotlight header strong{font-size:29px;color:#087c66}.spotlight header strong small{font-size:13px;color:#8290a1;margin-left:5px}.micro-kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:12px}.micro-kpis>div{position:relative;overflow:hidden;background:#fff;border:1px solid #e1e7ec;padding:13px 14px;display:flex;align-items:center;gap:11px;border-radius:6px}.micro-kpis>div:before{content:'';position:absolute;left:0;top:0;bottom:0;width:3px;background:#087c66}.micro-kpis .verify-kpi:before{background:#e09a23}.micro-kpis .point-kpi:before{background:#3378b8}.micro-kpis .like-kpi:before{background:#b35e86}.kpi-icon{display:grid!important;place-items:center;width:34px!important;height:34px;border-radius:50%;background:#e8f4f1;color:#087c66}.verify-kpi .kpi-icon{background:#fff4df;color:#c47c12}.point-kpi .kpi-icon{background:#eaf2fb;color:#3378b8}.like-kpi .kpi-icon{background:#faedf3;color:#b35e86}.kpi-icon svg{width:17px}.micro-kpis>div>div{min-width:0;flex:1}.micro-kpis small,.micro-kpis>div>div>span{display:block;font-size:13px;color:#7d8999}.micro-kpis b{display:block;font-size:23px;line-height:1.15;color:#182334;margin:2px 0}.micro-kpis em{font-style:normal;font-size:13px;color:#7d8999;margin-left:3px}.dashx-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.dx-panel{background:#fff;border:1px solid #e5eaf0;border-radius:7px;padding:14px;min-width:0}.dx-panel header{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:9px}.dx-panel h2{font-size:15px;margin:0 0 3px}.dx-panel header p{margin:0;color:#8792a2;font-size:14px}.dx-panel header>svg{width:18px;color:#087c66}.mentor-board article{display:flex;gap:10px;padding:9px 0;border-top:1px solid #eef1f5}.mentor-board i{width:4px;background:#e0a128;border-radius:3px}.mentor-board i.safety{background:#d94b42}.mentor-board .like-note i{background:#087c66}.mentor-board p{margin:3px 0;line-height:1.45;color:#425169;font-size:15px}.mentor-board small{color:#929cac;font-size:13px}.calendar-head,.heat-grid{display:grid;grid-template-columns:repeat(7,1fr);gap:4px}.calendar-head span{text-align:center;font-size:13px;color:#8b96a7}.heat-grid button{border:0;background:transparent;height:35px;position:relative;border-radius:5px;cursor:pointer}.heat-grid button span{display:grid;place-items:center;width:25px;height:25px;margin:auto;border-radius:50%;background:#eef2f4;color:#536175;font-size:14px}.heat-grid button small{position:absolute;right:2px;bottom:0;color:#8a95a6;font-size:11px}.heat-grid .lv1 span{background:#d9eee7}.heat-grid .lv2 span{background:#a8d8c9}.heat-grid .lv3 span{background:#5db69d;color:#fff}.heat-grid .lv4 span{background:#087c66;color:#fff}.heat-grid button.active{outline:2px solid #e5a323}.heat-legend{display:flex;justify-content:flex-end;align-items:center;gap:4px;margin-top:6px;font-size:12px;color:#8a95a6}.heat-legend i{width:9px;height:9px;background:#eef2f4}.heat-legend .lv1{background:#d9eee7}.heat-legend .lv2{background:#a8d8c9}.heat-legend .lv3{background:#5db69d}.heat-legend .lv4{background:#087c66}.hourly{grid-column:1/-1}.hour-strip{display:grid;grid-template-columns:repeat(12,minmax(62px,1fr));overflow:auto}.hour-strip.compact{grid-template-columns:repeat(6,1fr)}.hour-strip>div{text-align:center;padding:6px 5px;border-left:1px solid #edf0f3;display:grid;grid-template-columns:1fr 1fr;gap:2px}.hour-strip small,.hour-strip em{font-style:normal;font-size:12px;color:#8390a2}.hour-strip b{font-size:15px}.hour-strip span{font-size:13px;color:#3c5a75}.week-switch{display:grid;grid-template-columns:repeat(7,1fr);gap:7px}.week-switch button{position:relative;border:1px solid #e2e7ed;background:#fafbfc;border-radius:5px;padding:8px;cursor:pointer}.week-switch button.active{background:#087c66;color:#fff;border-color:#087c66}.week-switch span{display:block;font-size:13px}.week-switch i{position:absolute;right:6px;top:6px;font-style:normal;font-size:12px;background:#e7ecef;color:#546275;border-radius:9px;min-width:17px}.week-switch button.active i{background:#fff;color:#087c66}.agenda-list article{display:grid;grid-template-columns:55px 1fr minmax(100px,160px) auto;align-items:center;gap:12px;padding:9px 4px;border-bottom:1px solid #edf0f3}.agenda-list time{font-weight:700;color:#087c66}.agenda-list span{display:block;font-size:14px;color:#8490a1;margin-top:3px}.expanded .dx-panel{padding:18px}.expanded .mentor-board article{padding:12px 0}.expanded .heat-grid button{height:42px}.expanded .heat-grid button span{width:29px;height:29px}.expanded .hour-strip>div{display:flex;flex-direction:column;padding:9px 5px;gap:5px}@media(max-width:900px){.micro-kpis{grid-template-columns:1fr 1fr}.dashx-grid{grid-template-columns:1fr}.hour-strip,.hour-strip.compact{grid-template-columns:repeat(6,76px)}.weather-now{display:none}.agenda-list article{grid-template-columns:50px 1fr auto}.agenda-list .el-progress{display:none}}@media(max-width:520px){.micro-kpis{grid-template-columns:1fr}.dx-panel{padding:12px}.dash-head-actions{width:100%;justify-content:flex-end}.spotlight{padding:13px}.week-switch{gap:3px}.week-switch button{padding:7px 3px}}
.micro-kpis small{font-size:16px!important;font-weight:700;color:#536174!important}.micro-kpis b{font-size:29px!important;margin:4px 0!important}.micro-kpis>div>div>span{font-size:14px!important}.safety-weather{grid-column:1/-1}.weather-alerts{display:grid;gap:7px}.weather-alerts article{display:grid;grid-template-columns:minmax(190px,280px) 1fr;gap:14px;padding:10px 12px;border-left:4px solid #e09a23;background:#fff8e9}.weather-alerts article.danger{border-color:#d94b42;background:#fff0ef}.weather-alerts article.rain{border-color:#3378b8;background:#edf5fc}.weather-alerts b{font-size:15px}.weather-alerts span{font-size:14px;color:#526175;line-height:1.5}.weather-safe{display:flex;align-items:center;gap:9px;padding:10px 12px;background:#edf7f3;color:#32675a;font-size:14px}.weather-safe svg{width:17px}@media(max-width:650px){.weather-alerts article{grid-template-columns:1fr;gap:4px}.micro-kpis b{font-size:25px!important}}
.weather-brief{max-width:500px;text-align:right}.weather-brief p{margin:4px 0 0;font-size:13px;line-height:1.4;color:#7a8695}.weather-brief .weather-now{justify-content:flex-end}.dashx .spotlight{box-shadow:none;border-color:#dfe5e8;border-left:1px solid #dfe5e8;border-top:3px solid #087c66;border-radius:4px}.dashx .micro-kpis>div{border-color:#e3e7ea;border-radius:4px;box-shadow:none}.dashx .micro-kpis>div:before{width:2px;background:#cfd8d5}.dashx .micro-kpis .progress-kpi:before{background:#087c66}.dashx .verify-kpi .kpi-icon,.dashx .point-kpi .kpi-icon,.dashx .like-kpi .kpi-icon,.dashx .kpi-icon{background:#f1f4f4;color:#49615b}.dashx .dx-panel{border-radius:4px;border-color:#e3e7ea}.dashx .week-switch button{border-radius:3px;background:#fff}.dashx .week-switch button.active{background:#153f38;border-color:#153f38}.dashx .agenda-list article:last-child{border-bottom:0}.dashx .page-title h1{letter-spacing:0}.dashx .eyebrow{color:#087c66}@media(max-width:900px){.weather-brief{display:none}}
.dashx{--surface:#fff;--line:#dfe6e8;--green:#087c66}.dashx .page-title{padding-bottom:4px}.weather-brief{padding:9px 12px;background:#f3f7f6;border:1px solid #dce7e3;border-radius:6px}.dashx .spotlight{position:relative;overflow:hidden;border:1px solid #d8e5e1;border-left:4px solid var(--green);border-top:1px solid #d8e5e1;border-radius:6px;box-shadow:0 7px 22px rgba(31,67,61,.08)}.dashx .spotlight:after{content:'';position:absolute;right:0;top:0;width:120px;height:3px;background:#e6aa39}.dashx .micro-kpis>div{border-radius:6px;box-shadow:0 3px 12px rgba(28,49,58,.055);transition:transform .18s ease,box-shadow .18s ease}.dashx .micro-kpis>div:hover{transform:translateY(-1px);box-shadow:0 7px 18px rgba(28,49,58,.09)}.dashx .micro-kpis>div:before{width:3px}.dashx .progress-kpi:before{background:#087c66}.dashx .verify-kpi:before{background:#d69a2d}.dashx .point-kpi:before{background:#3579a8}.dashx .like-kpi:before{background:#9b6482}.dashx .kpi-icon{background:#e8f3f0;color:#087c66}.dashx .verify-kpi .kpi-icon{background:#fff4df;color:#b97917}.dashx .point-kpi .kpi-icon{background:#eaf2f8;color:#3579a8}.dashx .like-kpi .kpi-icon{background:#f6edf2;color:#9b6482}.dashx .dx-panel{border-radius:6px;box-shadow:0 3px 13px rgba(28,49,58,.05)}.dashx .mentor-board{border-top:3px solid #d69a2d}.dashx .workload{border-top:3px solid #4d9583}.dashx .week-switch button{border-radius:5px;background:#f8faf9}.dashx .week-switch button:hover{border-color:#8fb9ae;background:#f1f7f5}.dashx .week-switch button.active{background:#0b705f;border-color:#0b705f;box-shadow:0 4px 10px rgba(8,124,102,.18)}.dashx .agenda-list article{border-radius:4px;padding-left:10px;padding-right:10px}.dashx .agenda-list article:hover{background:#f7faf9}.dashx .heat-grid button.active{outline:2px solid #d9a13b;outline-offset:-1px}@media(max-width:900px){.weather-brief{display:none}.dashx .micro-kpis>div:hover{transform:none}}
