.dashx.is-loading{position:relative;min-height:650px}.dashx.is-loading>:not(.loading-skeleton){visibility:hidden}.loading-skeleton{position:absolute;inset:24px;z-index:5;background:#f5f7fa;padding:12px}.loading-skeleton :deep(.el-skeleton__item){background:linear-gradient(90deg,#e8edef 25%,#f5f7f8 37%,#e8edef 63%);background-size:400% 100%}
.heat-grid button.today span{box-shadow:0 0 0 2px #fff,0 0 0 4px #d79b2e;font-weight:800}.heat-grid button.today:after{content:'今';position:absolute;left:50%;bottom:-3px;transform:translateX(-50%);font-size:11px;color:#a76d0e}
